using KugouAvaloniaPlayer.Models;
using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Threading;
using System.Threading.Tasks;
using Microsoft.Data.Sqlite;
namespace KugouAvaloniaPlayer.Services;
public sealed partial class LocalMusicLibraryService {
 internal async Task<IReadOnlyList<LocalTrackItem>> GetAllLocalTracksAsync(){await EnsureInitializedAsync(CancellationToken.None);await using var c=await AppDatabase.CreateConnectionAsync();using var q=c.CreateCommand();q.CommandText="SELECT id,title,artist,album,duration_seconds,source_type,local_path,cover_path,remote_url FROM tracks WHERE source_type='LocalFile' ORDER BY id";using var r=await q.ExecuteReaderAsync();var rows=new List<LocalTrackItem>();while(await r.ReadAsync())rows.Add(ReadTrackItem(r));return rows;}
 internal static string DemandPlaylistName(string name){name=name.Trim();if(name.Length is <1 or >80||name.Any(c=>char.IsControl(c)||"<>:\"/\\|?*".Contains(c)))throw new ArgumentException("名称须为1–80字符，不能包含路径或控制字符");return name;}
 static async Task DemandUniqueName(SqliteConnection c,SqliteTransaction tx,string name,long except){using var q=c.CreateCommand();q.Transaction=tx;q.CommandText="SELECT id,name FROM playlists";using var rd=await q.ExecuteReaderAsync();while(await rd.ReadAsync())if(rd.GetInt64(0)!=except&&string.Equals(rd.GetString(1).Trim(),name,StringComparison.OrdinalIgnoreCase))throw new InvalidOperationException("已有同名歌单；未覆盖");}
 static async Task DemandTrackReferences(SqliteConnection c,SqliteTransaction tx,IReadOnlyList<long> ids){if(ids.Count>1000)throw new InvalidOperationException("最多1000条；未静默截断");foreach(var id in ids){using var q=c.CreateCommand();q.Transaction=tx;q.CommandText="SELECT local_path,source_type,remote_url FROM tracks WHERE id=$id";q.Parameters.AddWithValue("$id",id);using var rd=await q.ExecuteReaderAsync();if(!await rd.ReadAsync()||rd.GetString(1)!="LocalFile"||!rd.IsDBNull(2)&&!string.IsNullOrEmpty(rd.GetString(2)))throw new IOException("曲目引用无效");if (Startup.OfflineStartupProfile.Active) Startup.OfflineStartupProfile.Current.DemandMedia(rd.GetString(0));}}
 internal async Task<LocalPlaylistSummary> SaveOrderedPlaylistAsync(string name,IReadOnlyList<long> ids){name=DemandPlaylistName(name);if(ids.Count==0)throw new InvalidOperationException("空队列不能保存");await EnsureInitializedAsync(CancellationToken.None);await using var c=await AppDatabase.CreateConnectionAsync();using var tx=c.BeginTransaction();await DemandUniqueName(c,tx,name,0);await DemandTrackReferences(c,tx,ids);var now=DateTime.UtcNow;var entity=new LocalPlaylistEntity{Name=name,Kind=PlaylistKindManual,CreatedAtUtc=now,UpdatedAtUtc=now};entity.Id=await InsertPlaylistAsync(c,tx,entity,CancellationToken.None);for(int i=0;i<ids.Count;i++)await InsertPlaylistTrackAsync(c,tx,entity.Id,ids[i],i,now,CancellationToken.None);await tx.CommitAsync();return await GetPlaylistSummaryAsync(c,null,entity.Id,CancellationToken.None);}
 internal async Task ReplaceOrderedTracksAsync(long id,IReadOnlyList<long> tracks){await EnsureInitializedAsync(CancellationToken.None);await using var c=await AppDatabase.CreateConnectionAsync();using var tx=c.BeginTransaction();if(await GetPlaylistAsync(c,tx,id,CancellationToken.None)==null)throw new InvalidOperationException("歌单不存在");await DemandTrackReferences(c,tx,tracks);await DeletePlaylistTracksAsync(c,tx,id,CancellationToken.None);for(int i=0;i<tracks.Count;i++)await InsertPlaylistTrackAsync(c,tx,id,tracks[i],i,DateTime.UtcNow,CancellationToken.None);await tx.CommitAsync();}
 internal async Task RenameStrictAsync(long id,string name){name=DemandPlaylistName(name);await EnsureInitializedAsync(CancellationToken.None);await using var c=await AppDatabase.CreateConnectionAsync();using var tx=c.BeginTransaction();await DemandUniqueName(c,tx,name,id);var p=await GetPlaylistAsync(c,tx,id,CancellationToken.None)??throw new InvalidOperationException("歌单不存在");p.Name=name;p.UpdatedAtUtc=DateTime.UtcNow;await UpdatePlaylistAsync(c,tx,p,CancellationToken.None);await tx.CommitAsync();}
}
